\begin{tikzpicture}[every node/.style={font=\large}]
\coordinate (A) at (0,0); \coordinate (B) at (3,0); \coordinate (C) at (4,0.8); \coordinate (D) at (1,0.8); \coordinate (P) at (2,3.2);
\draw (A)--(B)--(C); \draw[dashed] (C)--(D)--(A);
\draw (P)--(A) (P)--(B) (P)--(C); \draw[dashed] (P)--(D);
\end{tikzpicture}
[/tikz]

